// =============================================================================
// GATE — LEITURA SOB DEMANDA (runbook Sprint 1, Grupo 1, passo 3)
// O endpoint lê em ciclo lento, mas só deixamos passar UMA leitura
// quando alguém clica em "LER SNAPSHOT AGORA". Nada é escrito no CLP.
// =============================================================================
const TIMEOUT_MS = 5000;

if (msg.topic === "arm") {
    context.set("armed", true);
    node.status({ fill: "yellow", shape: "ring", text: "aguardando leitura do CLP..." });
    const armedAt = Date.now();
    context.set("armedAt", armedAt);
    setTimeout(function () {
        if (context.get("armed") === true && context.get("armedAt") === armedAt) {
            context.set("armed", false);
            node.status({ fill: "red", shape: "dot", text: "sem leitura em 5 s — ver conexão" });
            node.warn("Nenhuma leitura do CLP em " + TIMEOUT_MS / 1000 + " s. Verifique IP, cabo, rede e o status do nó s7 in.");
        }
    }, TIMEOUT_MS);
    return null;
}

if (context.get("armed") !== true) { return null; }   // leitura cíclica descartada
context.set("armed", false);
msg.source = "PLC";
node.status({ fill: "green", shape: "dot", text: "leitura capturada " + new Date().toLocaleTimeString() });
return msg;

// =============================================================================
// MONTA A TABELA DE EVIDÊNCIA: sinal | símbolo | endereço | tipo | valor lido
// Para comparar com a watch table do TIA Portal (runbook, passo 5).
// =============================================================================
const tags = flow.get("diag_tags") || [];
const raw = msg.payload || {};
const rows = tags.map(function (t) {
    const has = Object.prototype.hasOwnProperty.call(raw, t.symbol);
    return {
        sinal: t.signal, simbolo: t.symbol, endereco: t.addr, tipo: t.type,
        valor_lido: has ? raw[t.symbol] : null,
        lido: has
    };
});
const snap = {
    captured_at: new Date().toISOString(),
    source: msg.source,
    valid_for_plc_validation: msg.source === "PLC",
    endpoint_status: flow.get("diag_conn") || "desconhecido",
    tags_esperadas: rows.length,
    tags_lidas: rows.filter(r => r.lido).length,
    rows: rows
};
flow.set("last_diag", snap);
msg.payload = snap;
node.status({ fill: snap.source === "PLC" ? "green" : "blue", shape: "dot",
              text: snap.source + ": " + snap.tags_lidas + "/" + snap.tags_esperadas + " tags" });
return msg;

