// Snapshot SIMULADO (sem CLP) — serve para testar o formato da evidência.
// Resultado marcado como source = "SIMULATED": NÃO vale como validação do CLP.
const v = {};
for (const t of flow.get("diag_tags") || []) {
    v[t.symbol] = t.type === "INT" || t.type === "WORD" ? 0 : false;
}
v.processo_segurancaOK = true; v.montagem_segurancaOK = true; v.expedicao_segurancaOK = true;
msg.payload = v;
msg.source = "SIMULATED";
return msg;

// Guarda o status de conexão mostrado pelo nó s7 in (online / offline / erro)
flow.set("diag_conn", (msg.status && msg.status.text) || "desconhecido");
flow.set("diag_conn_at", new Date().toISOString());
return null;

// GET /diag/s7  -> último snapshot em JSON
msg.payload = flow.get("last_diag") || { aviso: "Nenhum snapshot ainda. Clique em LER SNAPSHOT AGORA." };
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /diag/s7.csv  -> último snapshot em CSV (abre no Excel). Salvar em docs/evidence/sprint1/
const s = flow.get("last_diag");
if (!s) { msg.statusCode = 404; msg.payload = "Nenhum snapshot ainda."; return msg; }
const q = (x) => '"' + String(x === null || x === undefined ? "" : x).replace(/"/g, '""') + '"';
const lines = [["captured_at", "source", "sinal", "simbolo", "endereco", "tipo", "valor_lido", "valor_tia", "confere"].join(";")];
for (const r of s.rows) {
    lines.push([s.captured_at, s.source, r.sinal, r.simbolo, r.endereco, r.tipo, r.valor_lido, "", ""].map(q).join(";"));
}
msg.payload = "\ufeff" + lines.join("\r\n");
msg.headers = {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": "attachment; filename=G1-leitura-s7-" + s.captured_at.replace(/[:.]/g, "-") + ".csv"
};
return msg;
